const replacements=Object.entries(legacy).sort((a,b)=>b[0].length-a[0].length);
export const hasLegacyText=value=>/\p{Script=Han}/u.test(String(value??''));
export function englishLabel(value,fallback=''){
 let text=String(value??fallback);if(!hasLegacyText(text))return text;
 for(const [before,after]of replacements)text=text.split(before).join(after);
 text=text.replace(/[\u3002]/g,'. ').replace(/[\uff0c\u3001]/g,', ').replace(/\uff1a/g,': ').replace(/\uff01/g,'!');
 return hasLegacyText(text)?fallback:text.trim();
}
export function itemEnglishName(item){
 if(item.nameEn&&!hasLegacyText(item.nameEn))return item.nameEn;
 if(item.name&&!hasLegacyText(item.name))return item.name;
 return item.type.split('.').at(-1).replace(/_/g,' ').replace(/([a-z])([A-Z0-9])/g,'$1 $2').replace(/([A-Z])([A-Z][a-z])/g,'$1 $2');
}
